        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class SlugifyTest(unittest.TestCase):
    def test_spec_examples(self):
        self.assertEqual(slugify("Héllo, Wörld!"), "hello-world")
        self.assertEqual(slugify("  C++ & Rust  "), "c-rust")
        self.assertEqual(slugify("a b", sep="_"), "a_b")

    def test_accents_are_decomposed(self):
        self.assertEqual(slugify("é"), "e")
        self.assertEqual(slugify("Crème Brûlée"), "creme-brulee")

    def test_other_non_ascii_is_dropped_not_split(self):
        self.assertEqual(slugify("a€b"), "ab")
        self.assertEqual(slugify("naïve 日本 test"), "naive-test")

    def test_runs_of_separators_collapse(self):
        self.assertEqual(slugify("a --- b"), "a-b")
        self.assertEqual(slugify("a  \t\n b"), "a-b")

    def test_no_leading_or_trailing_sep(self):
        self.assertEqual(slugify("--hi--"), "hi")
        self.assertEqual(slugify("...x..."), "x")

    def test_lowercases_and_keeps_digits(self):
        self.assertEqual(slugify("Version 2.0 RC1"), "version-2-0-rc1")

    def test_custom_sep(self):
        self.assertEqual(slugify("a b", sep="_"), "a_b")
        self.assertEqual(slugify("a b", sep=""), "ab")

    def test_sep_that_is_a_letter_is_not_stripped(self):
        self.assertEqual(slugify("hello", sep="x"), "hello")
        self.assertEqual(slugify("a b", sep="x"), "axb")

    def test_nothing_left_raises(self):
        for bad in ["!!!", "", "   ", "é€日"]:
            with self.subTest(text=bad):
                with self.assertRaises(ValueError):
                    slugify(bad)


class SlugCommandTest(unittest.TestCase):
    def test_default(self):
        self.assertEqual(run("slug", "Héllo, Wörld!"), (0, "hello-world\n", ""))

    def test_sep_option(self):
        self.assertEqual(run("slug", "a b", "--sep", "_"), (0, "a_b\n", ""))

    def test_nothing_left_is_error(self):
        code, out, err = run("slug", "!!!")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error:"))

    def test_listed_in_commands(self):
        code, out, _ = run("commands")
        self.assertEqual(code, 0)
        self.assertIn("slug", out.split())


if __name__ == "__main__":
    unittest.main()

